#define _POSIX_C_SOURCE 200112L
#include <stdlib.h>
#include <string.h>
#include <omp.h>

#if defined(__AVX512F__) || (defined(__AVX2__) && defined(__FMA__))
#include <immintrin.h>
#endif

#if defined(__AVX512F__)
#define MR 12
#define NR 32
#elif defined(__AVX2__) && defined(__FMA__)
#define MR 6
#define NR 16
#else
#define MR 4
#define NR 8
#endif

#define KC 256
#define NCB (256 / NR)

static float *g_buf = NULL;
static size_t g_cap = 0;

static float *get_buf(size_t nfl)
{
    if (nfl > g_cap) {
        void *p = NULL;
        free(g_buf);
        g_buf = NULL;
        g_cap = 0;
        if (posix_memalign(&p, 64, nfl * sizeof(float)) != 0)
            return NULL;
        g_buf = (float *)p;
        g_cap = nfl;
    }
    return g_buf;
}

static void pack_a(const float *A, float *dst, int n, int i0)
{
    int rows = (n - i0 < MR) ? (n - i0) : MR;
    for (int r = 0; r < rows; r++) {
        const float *src = A + (size_t)(i0 + r) * n;
        for (int k = 0; k < n; k++)
            dst[(size_t)k * MR + r] = src[k];
    }
    for (int r = rows; r < MR; r++)
        for (int k = 0; k < n; k++)
            dst[(size_t)k * MR + r] = 0.0f;
}

static void pack_b(const float *B, float *dst, int n, int j0)
{
    int cols = (n - j0 < NR) ? (n - j0) : NR;
    for (int k = 0; k < n; k++) {
        const float *src = B + (size_t)k * n + j0;
        float *d = dst + (size_t)k * NR;
        memcpy(d, src, (size_t)cols * sizeof(float));
        for (int c = cols; c < NR; c++)
            d[c] = 0.0f;
    }
}

#if defined(__AVX512F__)

static void kernel(int kc, const float *a, const float *b, float *c, int ldc,
                   int first, int mr, int nr)
{
    __m512 acc[MR][2];
    for (int r = 0; r < MR; r++) {
        acc[r][0] = _mm512_setzero_ps();
        acc[r][1] = _mm512_setzero_ps();
    }
    for (int k = 0; k < kc; k++) {
        __m512 b0 = _mm512_load_ps(b);
        __m512 b1 = _mm512_load_ps(b + 16);
        for (int r = 0; r < MR; r++) {
            __m512 av = _mm512_set1_ps(a[r]);
            acc[r][0] = _mm512_fmadd_ps(av, b0, acc[r][0]);
            acc[r][1] = _mm512_fmadd_ps(av, b1, acc[r][1]);
        }
        a += MR;
        b += NR;
    }
    if (mr == MR && nr == NR) {
        for (int r = 0; r < MR; r++) {
            float *cr = c + (size_t)r * ldc;
            if (first) {
                _mm512_storeu_ps(cr, acc[r][0]);
                _mm512_storeu_ps(cr + 16, acc[r][1]);
            } else {
                _mm512_storeu_ps(cr, _mm512_add_ps(acc[r][0], _mm512_loadu_ps(cr)));
                _mm512_storeu_ps(cr + 16, _mm512_add_ps(acc[r][1], _mm512_loadu_ps(cr + 16)));
            }
        }
    } else {
        __mmask16 m0 = (nr >= 16) ? (__mmask16)0xFFFF : (__mmask16)((1u << nr) - 1u);
        __mmask16 m1 = (nr >= 32) ? (__mmask16)0xFFFF
                     : (nr > 16) ? (__mmask16)((1u << (nr - 16)) - 1u) : (__mmask16)0;
        for (int r = 0; r < mr; r++) {
            float *cr = c + (size_t)r * ldc;
            __m512 v0 = acc[r][0], v1 = acc[r][1];
            if (!first) {
                v0 = _mm512_add_ps(v0, _mm512_maskz_loadu_ps(m0, cr));
                v1 = _mm512_add_ps(v1, _mm512_maskz_loadu_ps(m1, cr + 16));
            }
            _mm512_mask_storeu_ps(cr, m0, v0);
            _mm512_mask_storeu_ps(cr + 16, m1, v1);
        }
    }
}

#elif defined(__AVX2__) && defined(__FMA__)

static void kernel(int kc, const float *a, const float *b, float *c, int ldc,
                   int first, int mr, int nr)
{
    __m256 acc[MR][2];
    for (int r = 0; r < MR; r++) {
        acc[r][0] = _mm256_setzero_ps();
        acc[r][1] = _mm256_setzero_ps();
    }
    for (int k = 0; k < kc; k++) {
        __m256 b0 = _mm256_load_ps(b);
        __m256 b1 = _mm256_load_ps(b + 8);
        for (int r = 0; r < MR; r++) {
            __m256 av = _mm256_broadcast_ss(a + r);
            acc[r][0] = _mm256_fmadd_ps(av, b0, acc[r][0]);
            acc[r][1] = _mm256_fmadd_ps(av, b1, acc[r][1]);
        }
        a += MR;
        b += NR;
    }
    if (mr == MR && nr == NR) {
        for (int r = 0; r < MR; r++) {
            float *cr = c + (size_t)r * ldc;
            if (first) {
                _mm256_storeu_ps(cr, acc[r][0]);
                _mm256_storeu_ps(cr + 8, acc[r][1]);
            } else {
                _mm256_storeu_ps(cr, _mm256_add_ps(acc[r][0], _mm256_loadu_ps(cr)));
                _mm256_storeu_ps(cr + 8, _mm256_add_ps(acc[r][1], _mm256_loadu_ps(cr + 8)));
            }
        }
    } else {
        float tmp[MR * NR] __attribute__((aligned(32)));
        for (int r = 0; r < MR; r++) {
            _mm256_store_ps(tmp + r * NR, acc[r][0]);
            _mm256_store_ps(tmp + r * NR + 8, acc[r][1]);
        }
        for (int r = 0; r < mr; r++) {
            float *cr = c + (size_t)r * ldc;
            for (int j = 0; j < nr; j++)
                cr[j] = first ? tmp[r * NR + j] : cr[j] + tmp[r * NR + j];
        }
    }
}

#else

static void kernel(int kc, const float *a, const float *b, float *c, int ldc,
                   int first, int mr, int nr)
{
    float acc[MR][NR];
    for (int r = 0; r < MR; r++)
        for (int j = 0; j < NR; j++)
            acc[r][j] = 0.0f;
    for (int k = 0; k < kc; k++) {
        for (int r = 0; r < MR; r++) {
            float av = a[r];
            for (int j = 0; j < NR; j++)
                acc[r][j] += av * b[j];
        }
        a += MR;
        b += NR;
    }
    for (int r = 0; r < mr; r++) {
        float *cr = c + (size_t)r * ldc;
        for (int j = 0; j < nr; j++)
            cr[j] = first ? acc[r][j] : cr[j] + acc[r][j];
    }
}

#endif

static void matmul_naive(const float *A, const float *B, float *C, int n)
{
    for (int i = 0; i < n; i++) {
        float *ci = C + (size_t)i * n;
        for (int j = 0; j < n; j++)
            ci[j] = 0.0f;
        for (int k = 0; k < n; k++) {
            float aik = A[(size_t)i * n + k];
            const float *bk = B + (size_t)k * n;
            for (int j = 0; j < n; j++)
                ci[j] += aik * bk[j];
        }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0)
        return;

    int mp = (n + MR - 1) / MR;
    int np = (n + NR - 1) / NR;
    size_t asz = (size_t)mp * MR * n;
    asz = (asz + 15) & ~(size_t)15;
    size_t bsz = (size_t)np * NR * n;

    float *buf = get_buf(asz + bsz);
    if (!buf) {
        matmul_naive(A, B, C, n);
        return;
    }
    float *Ap = buf;
    float *Bp = buf + asz;

    int nth = omp_get_max_threads();
    if (nth < 1)
        nth = 1;
    int ntn = (np + NCB - 1) / NCB;
    int mpt = (int)(((long long)mp * ntn) / (4LL * nth));
    if (mpt < 1)
        mpt = 1;
    if (mpt > 8)
        mpt = 8;
    int ntm = (mp + mpt - 1) / mpt;
    int ntask = ntm * ntn;

    #pragma omp parallel
    {
        #pragma omp for schedule(static)
        for (int p = 0; p < mp; p++)
            pack_a(A, Ap + (size_t)p * MR * n, n, p * MR);

        #pragma omp for schedule(static)
        for (int q = 0; q < np; q++)
            pack_b(B, Bp + (size_t)q * NR * n, n, q * NR);

        #pragma omp for schedule(dynamic, 1)
        for (int t = 0; t < ntask; t++) {
            int tm = t / ntn;
            int tn = t % ntn;
            int p0 = tm * mpt;
            int p1 = p0 + mpt < mp ? p0 + mpt : mp;
            int q0 = tn * NCB;
            int q1 = q0 + NCB < np ? q0 + NCB : np;
            for (int pc = 0; pc < n; pc += KC) {
                int kc = (n - pc < KC) ? (n - pc) : KC;
                int first = (pc == 0);
                for (int p = p0; p < p1; p++) {
                    int i0 = p * MR;
                    int mr = (n - i0 < MR) ? (n - i0) : MR;
                    const float *ap = Ap + (size_t)p * MR * n + (size_t)pc * MR;
                    for (int q = q0; q < q1; q++) {
                        int j0 = q * NR;
                        int nr = (n - j0 < NR) ? (n - j0) : NR;
                        const float *bp = Bp + (size_t)q * NR * n + (size_t)pc * NR;
                        kernel(kc, ap, bp, C + (size_t)i0 * n + j0, n, first, mr, nr);
                    }
                }
            }
        }
    }
}
